[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Leap Studio — Your Reinvention and Experience Partner</title>
  <meta name="description" content="A global creative agency that challenges the status quo to create transformative experiences that win hearts and move markets in the eco-digital era.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --bg: #0A0A0A;
      --bg-elevated: #141414;
      --bg-card: #1A1A1A;
      --bg-card-hover: #222222;
      --text: #FFFFFF;
      --text-secondary: #A0A0A0;
      --text-muted: #666666;
      --accent: #3B82F6;
      --accent-hover: #60A5FA;
      --accent-warm: #F59E0B;
      --border: #2A2A2A;
      --border-light: #333333;
      --radius: 12px;
      --radius-sm: 8px;
      --radius-lg: 20px;
      --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
      --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      background: var(--bg);
      color: var(--text);
      line-height: 1.6;
      overflow-x: hidden;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    a { color: inherit; text-decoration: none; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; color: inherit; }
    img { display: block; max-width: 100%; }
    ul { list-style: none; }

    /* ===== NAVIGATION ===== */
    .nav {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      padding: 0 clamp(24px, 4vw, 64px);
      height: 72px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      background: rgba(10, 10, 10, 0.85);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      border-bottom: 1px solid rgba(255,255,255,0.06);
      transition: background var(--transition);
    }

    .nav-logo {
      font-size: 1.25rem;
      font-weight: 800;
      letter-spacing: -0.03em;
      white-space: nowrap;
    }

    .nav-logo span { color: var(--accent); }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .nav-links a {
      font-size: 0.875rem;
      font-weight: 500;
      color: var(--text-secondary);
      transition: color var(--transition);
      white-space: nowrap;
    }

    .nav-links a:hover { color: var(--text); }

    .nav-right {
      display: flex;
      align-items: center;
      gap: 20px;
    }

    .lang-selector {
      position: relative;
      font-size: 0.8125rem;
      font-weight: 500;
    }

    .lang-btn {
      display: flex;
      align-items: center;
      gap: 6px;
      padding: 6px 12px;
      border-radius: var(--radius-sm);
      color: var(--text-secondary);
      transition: all var(--transition);
    }

    .lang-btn:hover { color: var(--text); background: var(--bg-card); }

    .lang-btn svg {
      width: 14px;
      height: 14px;
      transition: transform var(--transition);
    }

    .lang-selector.open .lang-btn svg { transform: rotate(180deg); }

    .lang-dropdown {
      position: absolute;
      top: calc(100% + 8px);
      right: 0;
      min-width: 160px;
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
      padding: 4px;
      opacity: 0;
      visibility: hidden;
      transform: translateY(-8px);
      transition: all var(--transition);
      box-shadow: 0 20px 40px rgba(0,0,0,0.5);
    }

    .lang-selector.open .lang-dropdown {
      opacity: 1;
      visibility: visible;
      transform: translateY(0);
    }

    .lang-option {
      display: block;
      width: 100%;
      padding: 8px 12px;
      text-align: left;
      font-size: 0.8125rem;
      border-radius: 6px;
      color: var(--text-secondary);
      transition: all var(--transition);
    }

    .lang-option:hover { background: var(--bg-elevated); color: var(--text); }
    .lang-option.active { color: var(--accent); }

    .nav-contact {
      padding: 8px 20px;
      background: var(--text);
      color: var(--bg);
      border-radius: 100px;
      font-size: 0.8125rem;
      font-weight: 600;
      transition: all var(--transition);
    }

    .nav-contact:hover { background: var(--accent); color: var(--text); }

    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      width: 24px;
      padding: 4px 0;
    }

    .hamburger span {
      display: block;
      height: 2px;
      background: var(--text);
      border-radius: 2px;
      transition: all var(--transition);
    }

    /* Mobile nav */
    .mobile-menu {
      display: none;
      position: fixed;
      top: 72px;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--bg);
      z-index: 999;
      padding: 32px clamp(24px, 4vw, 64px);
      flex-direction: column;
      gap: 4px;
      overflow-y: auto;
    }

    .mobile-menu.open { display: flex; }

    .mobile-menu a {
      display: block;
      padding: 16px 0;
      font-size: 1.5rem;
      font-weight: 600;
      border-bottom: 1px solid var(--border);
      color: var(--text-secondary);
      transition: color var(--transition);
    }

    .mobile-menu a:hover { color: var(--text); }

    /* ===== HERO ===== */
    .hero {
      min-height: 100vh;
      padding-top: 72px;
      display: flex;
      flex-direction: column;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }

    .hero-carousel {
      position: relative;
      flex: 1;
      display: flex;
      align-items: center;
    }

    .hero-track {
      display: flex;
      transition: transform 0.7s cubic-bezier(0.4, 0, 0.2, 1);
      width: 100%;
    }

    .hero-slide {
      min-width: 100%;
      padding: clamp(40px, 8vh, 100px) clamp(24px, 4vw, 64px);
      display: flex;
      align-items: center;
      gap: clamp(32px, 4vw, 80px);
    }

    .hero-content {
      flex: 1;
      max-width: 680px;
    }

    .hero-tag {
      display: inline-block;
      padding: 6px 16px;
      background: rgba(59, 130, 246, 0.12);
      color: var(--accent);
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      border-radius: 100px;
      margin-bottom: 24px;
    }

    .hero-title {
      font-size: clamp(2.5rem, 5vw, 4.5rem);
      font-weight: 800;
      line-height: 1.05;
      letter-spacing: -0.03em;
      margin-bottom: 20px;
    }

    .hero-desc {
      font-size: clamp(1rem, 1.5vw, 1.25rem);
      color: var(--text-secondary);
      line-height: 1.6;
      max-width: 540px;
      margin-bottom: 36px;
    }

    .hero-cta {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      padding: 14px 32px;
      background: var(--accent);
      color: var(--text);
      border-radius: 100px;
      font-size: 0.9375rem;
      font-weight: 600;
      transition: all var(--transition);
    }

    .hero-cta:hover {
      background: var(--accent-hover);
      transform: translateY(-1px);
      box-shadow: 0 8px 24px rgba(59, 130, 246, 0.3);
    }

    .hero-cta svg { width: 18px; height: 18px; transition: transform var(--transition); }
    .hero-cta:hover svg { transform: translateX(3px); }

    .hero-image {
      flex: 1;
      max-width: 560px;
      aspect-ratio: 4/3;
      border-radius: var(--radius-lg);
      overflow: hidden;
      position: relative;
    }

    .hero-image-inner {
      width: 100%;
      height: 100%;
      background: linear-gradient(135deg, var(--bg-card), var(--bg-elevated));
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
    }

    .hero-image-inner::after {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(135deg, rgba(59,130,246,0.08), rgba(245,158,11,0.06));
    }

    .hero-image-placeholder {
      width: 64px;
      height: 64px;
      border-radius: 50%;
      border: 2px solid var(--border-light);
      display: flex;
      align-items: center;
      justify-content: center;
      opacity: 0.3;
    }

    .hero-controls {
      display: flex;
      align-items: center;
      gap: 16px;
      padding: 24px clamp(24px, 4vw, 64px) 40px;
    }

    .hero-dots {
      display: flex;
      gap: 8px;
    }

    .hero-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--border-light);
      transition: all var(--transition);
      cursor: pointer;
    }

    .hero-dot.active {
      background: var(--accent);
      width: 32px;
      border-radius: 4px;
    }

    .hero-arrows {
      display: flex;
      gap: 8px;
      margin-left: auto;
    }

    .hero-arrow {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      border: 1px solid var(--border-light);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: all var(--transition);
      color: var(--text-secondary);
    }

    .hero-arrow:hover {
      border-color: var(--text);
      color: var(--text);
      background: var(--bg-card);
    }

    .hero-arrow svg { width: 18px; height: 18px; }

    /* ===== SECTIONS COMMON ===== */
    .section {
      padding: clamp(64px, 10vh, 120px) clamp(24px, 4vw, 64px);
    }

    .section-header {
      margin-bottom: clamp(40px, 5vh, 64px);
    }

    .section-tag {
      display: inline-block;
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 16px;
    }

    .section-title {
      font-size: clamp(2rem, 3.5vw, 3.5rem);
      font-weight: 800;
      line-height: 1.1;
      letter-spacing: -0.03em;
      margin-bottom: 16px;
    }

    .section-subtitle {
      font-size: clamp(1rem, 1.5vw, 1.25rem);
      color: var(--text-secondary);
      max-width: 600px;
      line-height: 1.6;
    }

    /* ===== TEAM / GLOBAL STUDIOS ===== */
    .team-section { background: var(--bg-elevated); }

    .region-tabs {
      display: flex;
      gap: 4px;
      margin-bottom: 48px;
      background: var(--bg);
      border-radius: var(--radius);
      padding: 4px;
      width: fit-content;
      flex-wrap: wrap;
    }

    .region-tab {
      padding: 10px 24px;
      font-size: 0.875rem;
      font-weight: 500;
      border-radius: var(--radius-sm);
      color: var(--text-secondary);
      transition: all var(--transition);
      white-space: nowrap;
    }

    .region-tab:hover { color: var(--text); }

    .region-tab.active {
      background: var(--accent);
      color: var(--text);
    }

    .team-grid {
      display: none;
      gap: 24px;
    }

    .team-grid.active {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
      animation: fadeSlideIn 0.5s ease;
    }

    @keyframes fadeSlideIn {
      from { opacity: 0; transform: translateY(16px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .team-card {
      background: var(--bg);
      border-radius: var(--radius);
      overflow: hidden;
      border: 1px solid var(--border);
      transition: all var(--transition);
    }

    .team-card:hover {
      border-color: var(--border-light);
      transform: translateY(-4px);
      box-shadow: 0 20px 40px rgba(0,0,0,0.3);
    }

    .team-photo {
      width: 100%;
      aspect-ratio: 3/2;
      background: linear-gradient(135deg, #1a1a2e, #16213e);
      position: relative;
      overflow: hidden;
    }

    .team-photo::after {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(to bottom, transparent 50%, rgba(0,0,0,0.4));
    }

    .team-photo-initials {
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      width: 72px;
      height: 72px;
      border-radius: 50%;
      background: rgba(59,130,246,0.15);
      border: 1px solid rgba(59,130,246,0.3);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--accent);
      z-index: 1;
    }

    .team-info {
      padding: 24px;
    }

    .team-name {
      font-size: 1.125rem;
      font-weight: 700;
      margin-bottom: 4px;
    }

    .team-title {
      font-size: 0.8125rem;
      color: var(--accent);
      font-weight: 500;
      margin-bottom: 4px;
    }

    .team-office {
      font-size: 0.8125rem;
      color: var(--text-muted);
      margin-bottom: 16px;
    }

    .team-quote {
      font-size: 0.875rem;
      color: var(--text-secondary);
      line-height: 1.6;
      font-style: italic;
      margin-bottom: 20px;
      position: relative;
      padding-left: 16px;
      border-left: 2px solid var(--border-light);
    }

    .team-cta {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 0.8125rem;
      font-weight: 600;
      color: var(--accent);
      transition: all var(--transition);
    }

    .team-cta:hover { color: var(--accent-hover); gap: 10px; }
    .team-cta svg { width: 14px; height: 14px; }

    /* ===== WORK SHOWCASE ===== */
    .work-section { overflow: hidden; }

    .work-header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: clamp(40px, 5vh, 64px);
      flex-wrap: wrap;
      gap: 24px;
    }

    .work-scroll-container {
      overflow-x: auto;
      overflow-y: hidden;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
      cursor: grab;
      padding-bottom: 16px;
    }

    .work-scroll-container::-webkit-scrollbar { display: none; }
    .work-scroll-container:active { cursor: grabbing; }

    .work-track {
      display: flex;
      gap: 24px;
      width: max-content;
      padding-right: clamp(24px, 4vw, 64px);
    }

    .work-card {
      width: clamp(300px, 35vw, 480px);
      flex-shrink: 0;
      border-radius: var(--radius);
      overflow: hidden;
      background: var(--bg-card);
      border: 1px solid var(--border);
      transition: all var(--transition);
      position: relative;
    }

    .work-card:hover {
      border-color: var(--border-light);
      transform: translateY(-4px);
      box-shadow: 0 20px 40px rgba(0,0,0,0.3);
    }

    .work-thumb {
      width: 100%;
      aspect-ratio: 16/10;
      position: relative;
      overflow: hidden;
    }

    .work-thumb-bg {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 0.75rem;
      font-weight: 600;
      color: var(--text-muted);
      letter-spacing: 0.05em;
      text-transform: uppercase;
    }

    .work-card:nth-child(1) .work-thumb-bg { background: linear-gradient(135deg, #1a1a2e, #0f3460); }
    .work-card:nth-child(2) .work-thumb-bg { background: linear-gradient(135deg, #1a1a1a, #2d2d2d); }
    .work-card:nth-child(3) .work-thumb-bg { background: linear-gradient(135deg, #0a1628, #1a2a4a); }
    .work-card:nth-child(4) .work-thumb-bg { background: linear-gradient(135deg, #1a1a0a, #2a2a1a); }
    .work-card:nth-child(5) .work-thumb-bg { background: linear-gradient(135deg, #1a0a1a, #2a1a2a); }
    .work-card:nth-child(6) .work-thumb-bg { background: linear-gradient(135deg, #0a1a0a, #1a2a1a); }
    .work-card:nth-child(7) .work-thumb-bg { background: linear-gradient(135deg, #1a1428, #2a2438); }
    .work-card:nth-child(8) .work-thumb-bg { background: linear-gradient(135deg, #281a0a, #382a1a); }

    .work-card-body {
      padding: 24px;
    }

    .work-client {
      font-size: 0.75rem;
      font-weight: 600;
      color: var(--accent);
      letter-spacing: 0.05em;
      text-transform: uppercase;
      margin-bottom: 8px;
    }

    .work-card-title {
      font-size: 1.125rem;
      font-weight: 700;
      line-height: 1.3;
      margin-bottom: 12px;
    }

    .work-testimonial {
      font-size: 0.8125rem;
      color: var(--text-secondary);
      line-height: 1.6;
      font-style: italic;
      margin-bottom: 8px;
    }

    .work-attribution {
      font-size: 0.75rem;
      color: var(--text-muted);
      font-weight: 500;
    }

    .work-nav {
      display: flex;
      gap: 8px;
    }

    .work-nav-btn {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      border: 1px solid var(--border-light);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--text-secondary);
      transition: all var(--transition);
    }

    .work-nav-btn:hover {
      border-color: var(--text);
      color: var(--text);
      background: var(--bg-card);
    }

    .work-nav-btn svg { width: 18px; height: 18px; }

    /* ===== CTA BANNER ===== */
    .cta-banner {
      padding: clamp(64px, 10vh, 120px) clamp(24px, 4vw, 64px);
    }

    .cta-inner {
      background: linear-gradient(135deg, #111827, #1e293b);
      border-radius: var(--radius-lg);
      padding: clamp(48px, 6vh, 80px) clamp(32px, 4vw, 64px);
      text-align: center;
      position: relative;
      overflow: hidden;
      border: 1px solid var(--border);
    }

    .cta-inner::before {
      content: '';
      position: absolute;
      top: -50%;
      left: -50%;
      width: 200%;
      height: 200%;
      background: radial-gradient(ellipse at 30% 50%, rgba(59,130,246,0.08), transparent 60%);
      pointer-events: none;
    }

    .cta-banner-title {
      font-size: clamp(2rem, 4vw, 3.5rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      margin-bottom: 16px;
      position: relative;
    }

    .cta-banner-text {
      font-size: clamp(1rem, 1.3vw, 1.125rem);
      color: var(--text-secondary);
      max-width: 640px;
      margin: 0 auto 36px;
      line-height: 1.6;
      position: relative;
    }

    .cta-banner-btn {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      padding: 16px 36px;
      background: var(--accent);
      color: var(--text);
      border-radius: 100px;
      font-size: 1rem;
      font-weight: 600;
      transition: all var(--transition);
      position: relative;
    }

    .cta-banner-btn:hover {
      background: var(--accent-hover);
      transform: translateY(-2px);
      box-shadow: 0 12px 32px rgba(59, 130, 246, 0.3);
    }

    .cta-banner-btn svg { width: 18px; height: 18px; }

    /* ===== HOW WE WORK ===== */
    .how-section {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: clamp(40px, 6vw, 100px);
      align-items: center;
    }

    .how-visual {
      aspect-ratio: 1;
      max-width: 520px;
      border-radius: var(--radius-lg);
      background: linear-gradient(135deg, #0f172a, #1e293b);
      position: relative;
      overflow: hidden;
      border: 1px solid var(--border);
    }

    .how-visual::before {
      content: '';
      position: absolute;
      inset: 0;
      background: radial-gradient(circle at 30% 70%, rgba(59,130,246,0.1), transparent 60%),
                  radial-gradient(circle at 70% 30%, rgba(245,158,11,0.06), transparent 60%);
    }

    .how-visual-label {
      position: absolute;
      bottom: 24px;
      left: 24px;
      font-size: 0.75rem;
      color: var(--text-muted);
      font-weight: 500;
      letter-spacing: 0.05em;
      text-transform: uppercase;
    }

    .how-content {}

    .how-eyebrow {
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 16px;
    }

    .how-title {
      font-size: clamp(2rem, 3vw, 3rem);
      font-weight: 800;
      line-height: 1.1;
      letter-spacing: -0.03em;
      margin-bottom: 24px;
    }

    .how-text {
      font-size: 1rem;
      color: var(--text-secondary);
      line-height: 1.7;
      margin-bottom: 36px;
    }

    .how-cta {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      padding: 14px 32px;
      border: 1px solid var(--text);
      color: var(--text);
      border-radius: 100px;
      font-size: 0.9375rem;
      font-weight: 600;
      transition: all var(--transition);
    }

    .how-cta:hover {
      background: var(--text);
      color: var(--bg);
    }

    .how-cta svg { width: 18px; height: 18px; }

    /* ===== LATEST INSIGHTS ===== */
    .insights-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
      gap: 24px;
    }

    .insight-card {
      background: var(--bg-card);
      border-radius: var(--radius);
      overflow: hidden;
      border: 1px solid var(--border);
      transition: all var(--transition);
    }

    .insight-card:hover {
      border-color: var(--border-light);
      transform: translateY(-4px);
      box-shadow: 0 20px 40px rgba(0,0,0,0.3);
    }

    .insight-thumb {
      width: 100%;
      aspect-ratio: 16/9;
      position: relative;
      overflow: hidden;
    }

    .insight-card:nth-child(odd) .insight-thumb { background: linear-gradient(135deg, #1a1a2e, #0f3460); }
    .insight-card:nth-child(even) .insight-thumb { background: linear-gradient(135deg, #2d1a1a, #1a0a2e); }

    .insight-type-badge {
      position: absolute;
      top: 12px;
      left: 12px;
      padding: 4px 12px;
      background: rgba(10, 10, 10, 0.8);
      backdrop-filter: blur(8px);
      border-radius: 100px;
      font-size: 0.6875rem;
      font-weight: 600;
      letter-spacing: 0.05em;
      text-transform: uppercase;
      color: var(--accent);
    }

    .insight-body {
      padding: 20px;
    }

    .insight-title {
      font-size: 1rem;
      font-weight: 700;
      line-height: 1.3;
      margin-bottom: 16px;
    }

    .insight-cta {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 0.8125rem;
      font-weight: 600;
      color: var(--accent);
      transition: all var(--transition);
    }

    .insight-cta:hover { color: var(--accent-hover); gap: 10px; }
    .insight-cta svg { width: 14px; height: 14px; }

    /* ===== PRINCIPLES ===== */
    .principles-section { background: var(--bg-elevated); }

    .principles-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
      gap: 24px;
      counter-reset: principle;
    }

    .principle-card {
      background: var(--bg);
      border-radius: var(--radius);
      padding: 32px;
      border: 1px solid var(--border);
      transition: all var(--transition);
      counter-increment: principle;
      position: relative;
    }

    .principle-card:hover {
      border-color: var(--accent);
      transform: translateY(-4px);
      box-shadow: 0 20px 40px rgba(0,0,0,0.3);
    }

    .principle-number {
      font-size: 3rem;
      font-weight: 800;
      color: var(--border-light);
      line-height: 1;
      margin-bottom: 20px;
      letter-spacing: -0.05em;
    }

    .principle-title {
      font-size: 1.25rem;
      font-weight: 700;
      margin-bottom: 12px;
      line-height: 1.2;
    }

    .principle-text {
      font-size: 0.875rem;
      color: var(--text-secondary);
      line-height: 1.6;
    }

    /* ===== FOOTER ===== */
    .footer {
      border-top: 1px solid var(--border);
    }

    .footer-top {
      padding: clamp(64px, 8vh, 100px) clamp(24px, 4vw, 64px);
      display: grid;
      grid-template-columns: 1.5fr 1fr 1fr;
      gap: clamp(40px, 4vw, 80px);
    }

    .footer-brand {}

    .footer-logo {
      font-size: 1.5rem;
      font-weight: 800;
      letter-spacing: -0.03em;
      margin-bottom: 20px;
    }

    .footer-logo span { color: var(--accent); }

    .footer-tagline {
      font-size: 0.9375rem;
      color: var(--text-secondary);
      line-height: 1.6;
      max-width: 360px;
      margin-bottom: 32px;
    }

    .footer-ctas {
      display: flex;
      gap: 12px;
      flex-wrap: wrap;
    }

    .footer-cta-primary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 12px 24px;
      background: var(--accent);
      color: var(--text);
      border-radius: 100px;
      font-size: 0.875rem;
      font-weight: 600;
      transition: all var(--transition);
    }

    .footer-cta-primary:hover {
      background: var(--accent-hover);
    }

    .footer-cta-secondary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 12px 24px;
      border: 1px solid var(--border-light);
      color: var(--text);
      border-radius: 100px;
      font-size: 0.875rem;
      font-weight: 600;
      transition: all var(--transition);
    }

    .footer-cta-secondary:hover {
      border-color: var(--text);
      background: rgba(255,255,255,0.05);
    }

    .footer-col h4 {
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--text-muted);
      margin-bottom: 20px;
    }

    .footer-col a {
      display: block;
      padding: 6px 0;
      font-size: 0.9375rem;
      color: var(--text-secondary);
      transition: color var(--transition);
    }

    .footer-col a:hover { color: var(--text); }

    .footer-bottom {
      padding: 24px clamp(24px, 4vw, 64px);
      border-top: 1px solid var(--border);
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 16px;
    }

    .footer-legal {
      font-size: 0.75rem;
      color: var(--text-muted);
    }

    .footer-legal-links {
      display: flex;
      gap: 24px;
    }

    .footer-legal-links a {
      font-size: 0.75rem;
      color: var(--text-muted);
      transition: color var(--transition);
    }

    .footer-legal-links a:hover { color: var(--text-secondary); }

    /* ===== COOKIE BANNER ===== */
    .cookie-banner {
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      z-index: 2000;
      background: var(--bg-card);
      border-top: 1px solid var(--border);
      padding: 20px clamp(24px, 4vw, 64px);
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
      transform: translateY(0);
      transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
      box-shadow: 0 -10px 40px rgba(0,0,0,0.4);
      flex-wrap: wrap;
    }

    .cookie-banner.hidden {
      transform: translateY(100%);
      pointer-events: none;
    }

    .cookie-text {
      font-size: 0.875rem;
      color: var(--text-secondary);
      line-height: 1.5;
      flex: 1;
      min-width: 240px;
    }

    .cookie-actions {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
    }

    .cookie-btn {
      padding: 10px 20px;
      border-radius: 100px;
      font-size: 0.8125rem;
      font-weight: 600;
      transition: all var(--transition);
      white-space: nowrap;
    }

    .cookie-accept {
      background: var(--accent);
      color: var(--text);
    }

    .cookie-accept:hover { background: var(--accent-hover); }

    .cookie-manage {
      border: 1px solid var(--border-light);
      color: var(--text-secondary);
    }

    .cookie-manage:hover {
      border-color: var(--text-secondary);
      color: var(--text);
    }

    .cookie-decline {
      color: var(--text-muted);
      padding: 10px 12px;
    }

    .cookie-decline:hover { color: var(--text-secondary); }

    /* ===== RESPONSIVE ===== */
    @media (max-width: 1024px) {
      .hero-slide { flex-direction: column; text-align: center; }
      .hero-content { max-width: 100%; }
      .hero-desc { margin-left: auto; margin-right: auto; }
      .hero-image { max-width: 400px; width: 100%; }
      .how-section { grid-template-columns: 1fr; }
      .how-visual { max-width: 100%; aspect-ratio: 16/9; }
      .footer-top { grid-template-columns: 1fr; }
    }

    @media (max-width: 768px) {
      .nav-links { display: none; }
      .nav-contact { display: none; }
      .hamburger { display: flex; }
      .team-grid.active { grid-template-columns: 1fr; }
      .insights-grid { grid-template-columns: 1fr; }
      .principles-grid { grid-template-columns: 1fr; }
      .region-tabs { width: 100%; }
      .region-tab { flex: 1; text-align: center; padding: 10px 12px; }
      .footer-bottom { flex-direction: column; text-align: center; }
      .footer-legal-links { justify-content: center; }
    }

    @media (max-width: 480px) {
      .work-card { width: 85vw; }
      .hero-controls { flex-wrap: wrap; }
    }
  </style>
